fn frame(t: i32) {
    host::display::clear(0x000000);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    let mut px: i32 = 0;
    let mut py: i32 = 0;
    let mut a: i32 = 0;
    while a <= 256 {
        let mut c: i32 = host::math::cos(a * 2);
        if c < 0 { c = 0 - c; }
        let r: i32 = (140 * c) / 256;
        let x: i32 = cx + (r * host::math::cos(a + t / 4)) / 256;
        let y: i32 = cy + (r * host::math::sin(a + t / 4)) / 256;
        if a > 0 {
            host::display::draw_line(px, py, x, y, 0xff88bb);
        }
        px = x;
        py = y;
        a = a + 2;
    }
    host::display::fill_rect(cx - 2, cy - 2, 4, 4, 0xffffff);
    host::display::present();
}
